def wcd(pairs):
    min_a = min(pair[0] for pair in pairs)
    min_b = min(pair[1] for pair in pairs)
    common_factors = Counter()

    for i in range(2, min(min_a, min_b) + 1):
        if min_a % i == 0 and min_b % i == 0:
            common_factors[i] += 1

    if not common_factors:
        return -1

    max_common_factor = 1
    for factor, count in common_factors.items():
        if count == len(pairs):
            max_common_factor = max(max_common_factor, factor)

    return max_common_factor

