def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def wcd(pairs):
    gcd_values = [gcd(a, b) for a, b in pairs]
    prime_factors = []

    def get_prime_factors(n):
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    for g in gcd_values:
        prime_factors.extend(get_prime_factors(g))

    counter = Counter(prime_factors)
    common_primes = [p for p, c in counter.items() if c == len(gcd_values)]

    if common_primes:
        return min(common_primes)
    else:
        return -1

