from sys import stdin, stdout

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def wcd(pairs):
    g = gcd(pairs[0][0], pairs[0][1])
    for i in range(1, len(pairs)):
        g = gcd(g, gcd(pairs[i][0], pairs[i][1]))

    if g == 1:
        return -1

    for i in range(2, g + 1):
        if all(x % i == 0 or y % i == 0 for x, y in pairs):
            return i

    return -1

